package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Replacement for System.ArraySegment&lt;T&gt; (generated by CSharpToJava converter).
 */
public final class ArraySegment<T> {
    private final T[] array;
    private final byte[] byteArray;
    private final int offset;
    private final int count;

    public ArraySegment() {
        this.array = null;
        this.byteArray = null;
        this.offset = 0;
        this.count = 0;
    }

    public ArraySegment(T[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    public ArraySegment(T[] array, int offset, int count) {
        this.array = array;
        this.byteArray = null;
        this.offset = offset;
        this.count = count;
    }

    /** Primitive byte[] backing — mirrors C# ArraySegment&lt;byte&gt;. */
    public ArraySegment(byte[] array, int offset, int count) {
        this.array = null;
        this.byteArray = array;
        this.offset = offset;
        this.count = count;
    }

    /** Mirrors ArraySegment&lt;T&gt;.Array — the underlying byte[] when constructed from one. */
    @SuppressWarnings("unchecked")
    public T[] getArray() {
        return byteArray != null ? (T[]) (Object) byteArray : array;
    }

    /** The underlying byte[] for byte-array segments (call sites typed byte[]). */
    public byte[] getByteArray() {
        return byteArray;
    }

    /** Mirrors ArraySegment&lt;T&gt;.Offset. */
    public int getOffset() {
        return offset;
    }

    /** Mirrors ArraySegment&lt;T&gt;.Count. */
    public int getCount() {
        return count;
    }

    /** Mirrors ArraySegment&lt;T&gt;.AsSpan() — slice of the underlying array. */
    public Span<T> asSpan() {
        if (byteArray != null) {
            return new Span<>(byteArray, offset, count);
        }
        if (array == null) {
            return new Span<>();
        }
        return new Span<>(array, offset, count);
    }

    /** Mirrors ArraySegment&lt;T&gt;.AsMemory() — slice of the underlying array. */
    public ReadOnlyMemory<T> asMemory() {
        if (byteArray != null) {
            @SuppressWarnings("unchecked")
            T[] copy = (T[]) (Object) Arrays.copyOfRange(byteArray, offset, offset + count);
            return new ReadOnlyMemory<>(copy);
        }
        if (array == null) {
            return new ReadOnlyMemory<>();
        }
        @SuppressWarnings("unchecked")
        T[] copy = (T[]) Arrays.copyOfRange(array, offset, offset + count);
        return new ReadOnlyMemory<>(copy);
    }
}
